// The value-clean surface: schemas, types, consts, error codes and classes, and
// the model registry. Every `bare-*` import here is `import type` (erased at
// build), so it pulls no runtime dependency and no engine. `index.ts` re-exports
// it alongside the engine.
export { VERBOSITY, ERROR_CODES, RAG_ERROR_CODES, toolSchema, definePlugin, defineHandler, defineDuplexHandler, PLUGIN_LLM, PLUGIN_EMBEDDING, PLUGIN_WHISPER, PLUGIN_BCI, PLUGIN_NMT, PLUGIN_TTS, PLUGIN_OCR, PLUGIN_DIFFUSION, PLUGIN_VLA, PLUGIN_CLASSIFICATION, BUILTIN_PLUGINS, MODEL_TYPES, ModelType } from './schemas/index.js';
// The full value-clean schema, profiling, and constant barrels: the @qvac/sdk client
// and worker source every internal schema/const/profiling name from here, so it
// carries no duplicate copies. All value-clean (only erased `import type` touches
// `bare-*`), so this stays Node-safe.
export * from './schemas/index.js';
export * from './profiling/index.js';
export * from './constants/index.js';
// Value-clean helpers @qvac/sdk's registry codegen and server-side profiler reach
// for; not part of either barrel, so re-exported explicitly here.
export { getAddonFromEngine, resolveCanonicalEngine, ENGINE_TO_ADDON, LEGACY_ENGINE_TO_CANONICAL } from './schemas/engine-addon-map.js';
export { generateProfileId } from './profiling/clock.js';
export { readModelExecutionMs } from './profiling/model-execution.js';
export { readBackendDiagnostics } from './profiling/backend-diagnostics.js';
export { PUBLIC_MODEL_TYPES, ModelTypeAliases, modelTypeInputSchema, modelTypeSchema } from './schemas/model-types.js';
// Model registry constants
export * from './models/registry/index.js';
export { SUPPORTED_AUDIO_FORMATS } from './constants/audio.js';
// Error classes consumers need for `instanceof` checks: on rejected promises,
// and on the synchronous throws of `plugins()` / `registerPlugin` (the plugin
// group below).
export { InferenceCancelledError, ContextOverflowError, RequestIdConflictError, RequestNotFoundError, RequestRejectedByPolicyError, RequestValidationFailedError, ModelNotLoadedError, TranslationFailedError, PluginDefinitionInvalidError, PluginModelTypeReservedError, PluginAlreadyRegisteredError, PluginLoggingInvalidError } from './errors/index.js';
// Logging
export { getLogger, LOG_ID, ALL_LOG_ID } from './logging/index.js';
// Profiler
export { profiler, attachBackendDiagnostics } from './profiling/index.js';
